/* Additional simulated lecture 69–70 differential cases; no specimen images implied. */
(function(){'use strict';const bank=window.VPQ_NECROPSY_DIFFERENTIAL_CASES;if(!bank||!Array.isArray(bank.cases))return;const extra=[{"id":"n69-syringomyelia","lecture":"69","system":"CNS","title":"Cavalier with a cervical cord cavity","species":"Young adult Cavalier King Charles Spaniel","history":"Chronic neck scratching and pain, scoliosis and intermittent forelimb weakness; MRI demonstrates a fluid-filled longitudinal cavity in the cervical spinal cord.","gross":"Longitudinal fluid-filled intramedullary cavitation, sometimes associated with crowding at the craniocervical junction.","histo":"Fluid-filled cavitation within spinal parenchyma, gliosis and variable axonal loss; distinguish an ependymal-lined dilated central canal.","best":"Syringomyelia","morph":"Spinal cord: cervical intramedullary syrinx with surrounding gliosis","mechanism":"Altered CSF flow associated with craniocervical malformation can create or enlarge a syrinx and damage spinal cord tissue.","tests":"MRI of brain and spinal cord to define syrinx, craniocervical anatomy and associated disease.","ref":"L69 slide 13–15","options":[{"name":"Syringomyelia","supports":"The anatomic distribution, signalment and specific lesion pattern favor this diagnosis.","against":"Confirm with appropriate imaging, microscopy and ancillary testing; one finding alone is insufficient.","hist":"Fluid-filled cavitation within spinal parenchyma, gliosis and variable axonal loss; distinguish an ependymal-lined dilated central canal.","role":"best"},{"name":"Hydromyelia","supports":"Can form a central canal cavity","against":"Cavity involves the dilated ependymal-lined central canal rather than a parenchymal syrinx","hist":"Ependymal-lined expansion of central canal","role":"less"},{"name":"Intramedullary neoplasm","supports":"Can cause cord signs and cavitation","against":"Expect a cellular mass or infiltrative lesion, potentially with secondary syrinx","hist":"Neoplastic glia or other tumor cells","role":"less"},{"name":"Intervertebral disc extrusion","supports":"Can cause cervical pain and paresis","against":"Extradural compression rather than intramedullary CSF cavitation","hist":"Focal compressive axonal injury","role":"less"}]},{"id":"n69-meningioma","lecture":"69","system":"CNS","title":"Extra-axial forebrain mass in an older dog","species":"Older dog","history":"Months of progressively worsening seizures and behavior change; imaging finds a broad-based, extra-axial mass attached to dura, compressing the frontal lobe.","gross":"Firm, well-demarcated dural-based mass indenting underlying brain; potentially with mineralization.","histo":"Meningothelial spindle-to-epithelioid cells in whorls, often with psammoma bodies; mitotic activity and invasion vary.","best":"Meningioma","morph":"Forebrain: expansile extra-axial dural-based neoplasm","mechanism":"Meningeal-cell proliferation causes mass effect, edema and seizures; gross location helps distinguish from primary intra-axial gliomas.","tests":"MRI for extra-axial signs, histopathology for tumor typing and grade.","ref":"L69 slide 17","options":[{"name":"Meningioma","supports":"The anatomic distribution, signalment and specific lesion pattern favor this diagnosis.","against":"Confirm with appropriate imaging, microscopy and ancillary testing; one finding alone is insufficient.","hist":"Meningothelial spindle-to-epithelioid cells in whorls, often with psammoma bodies; mitotic activity and invasion vary.","role":"best"},{"name":"Oligodendroglioma","supports":"Produces seizures and a cerebral mass","against":"Usually intra-axial and infiltrative, not broad-based dural attachment","hist":"Round cells with perinuclear clearing and branching capillaries","role":"less"},{"name":"Choroid plexus tumor","supports":"Can produce intracranial hypertension","against":"Typically intraventricular rather than dural based","hist":"Papillary epithelial tumor","role":"less"},{"name":"Metastatic carcinoma","supports":"Can form cerebral masses","against":"Often multiple or with systemic primary, and cytomorphology differs","hist":"Epithelial nests or glands","role":"less"}]},{"id":"n69-hepatic-enceph","lecture":"69","system":"CNS","title":"Young dog with post-meal neurologic episodes","species":"Juvenile small-breed dog","history":"Intermittent head pressing, hypersalivation and disorientation after meals, with small liver, low BUN and increased bile acids; brain gross examination may be unrevealing.","gross":"Brain often lacks a distinctive gross lesion; chronic disease may cause subtle cerebral edema.","histo":"Astrocytic swelling and Alzheimer type II astrocytosis can occur, particularly with hyperammonemia.","best":"Hepatic encephalopathy associated with portosystemic shunting","morph":"Brain: metabolic/toxic encephalopathy with astrocytic changes","mechanism":"Portosystemic bypass of hepatic ammonia clearance exposes the brain to neurotoxins, altering astrocyte osmoregulation and neurotransmission.","tests":"Fasting/postprandial bile acids, ammonia handled correctly, hepatic vascular imaging and evaluation of liver function.","ref":"L69 slide 26","options":[{"name":"Hepatic encephalopathy associated with portosystemic shunting","supports":"The anatomic distribution, signalment and specific lesion pattern favor this diagnosis.","against":"Confirm with appropriate imaging, microscopy and ancillary testing; one finding alone is insufficient.","hist":"Astrocytic swelling and Alzheimer type II astrocytosis can occur, particularly with hyperammonemia.","role":"best"},{"name":"Thiamine deficiency","supports":"Causes central neurologic signs","against":"Cortical necrosis and dietary context differ from postprandial hyperammonemia","hist":"Laminar neuronal necrosis","role":"less"},{"name":"Meningoencephalitis","supports":"Can cause seizures and behavior change","against":"Inflammatory CSF and inflammatory parenchymal lesions expected","hist":"Perivascular leukocytes or microabscesses","role":"less"},{"name":"Lead toxicosis","supports":"Can cause seizures and gastrointestinal signs","against":"Exposure and toxicology, not shunt physiology, drive diagnosis","hist":"Cortical neuronal injury with nonspecific edema","role":"less"}]},{"id":"n69-wobbler","lecture":"69","system":"Spinal cord","title":"Giant-breed dog with cervical ataxia","species":"Young adult Great Dane","history":"Progressive pelvic limb ataxia and proprioceptive deficits with a stiff neck; cervical imaging shows vertebral canal narrowing and dynamic cord compression.","gross":"Narrowed cervical canal with focal chronic spinal cord flattening; lesions may be subtle without imaging.","histo":"Chronic white-matter axonal degeneration, myelin loss and gliosis at level of compression.","best":"Cervical vertebral stenotic myelopathy","morph":"Cervical spinal cord: chronic compressive degenerative myelopathy","mechanism":"Abnormal cervical vertebral development or degenerative changes narrow the canal, compressing long white-matter tracts.","tests":"MRI and targeted vertebral imaging including dynamic factors when clinically indicated.","ref":"L69 slide 43","options":[{"name":"Cervical vertebral stenotic myelopathy","supports":"The anatomic distribution, signalment and specific lesion pattern favor this diagnosis.","against":"Confirm with appropriate imaging, microscopy and ancillary testing; one finding alone is insufficient.","hist":"Chronic white-matter axonal degeneration, myelin loss and gliosis at level of compression.","role":"best"},{"name":"Degenerative myelopathy","supports":"Causes progressive proprioceptive deficits","against":"Usually nonpainful thoracolumbar signs without focal cervical compression","hist":"Bilateral tract degeneration","role":"less"},{"name":"Fibrocartilaginous embolism","supports":"Can cause ataxia and spinal cord dysfunction","against":"Usually acute nonprogressive onset with focal infarction","hist":"Ischemic necrosis with fibrocartilage in a vessel","role":"less"},{"name":"Discospondylitis","supports":"Cervical pain and ataxia can occur","against":"Expect infected endplates/discs and inflammation","hist":"Suppurative osteomyelitis/discitis","role":"less"}]},{"id":"n70-grass-sickness","lecture":"70","system":"PNS/ANS","title":"Horse with severe ileus and dry mucosa","species":"Adult grazing horse","history":"Sudden dysphagia, salivation, colic, dry nasal mucosa and severe gut hypomotility; some cases become chronically wasted with patchy sweating.","gross":"Marked gastrointestinal distension and impaction may dominate; neural lesions are generally not obvious grossly.","histo":"Chromatolysis and neuronal loss in autonomic and enteric ganglia, including cranial cervical ganglia and intestinal plexuses.","best":"Equine grass sickness (equine dysautonomia)","morph":"Autonomic/enteric ganglia: multifocal neuronal degeneration and loss","mechanism":"Dysautonomia disrupts parasympathetic and enteric control of motility and secretion, producing ileus and dysphagia; exact cause remains unresolved.","tests":"Clinical examination and exclusion of obstructive or other dysautonomic causes; histology of suitable autonomic ganglia supports diagnosis.","ref":"L70 slide 25","options":[{"name":"Equine grass sickness (equine dysautonomia)","supports":"The anatomic distribution, signalment and specific lesion pattern favor this diagnosis.","against":"Confirm with appropriate imaging, microscopy and ancillary testing; one finding alone is insufficient.","hist":"Chromatolysis and neuronal loss in autonomic and enteric ganglia, including cranial cervical ganglia and intestinal plexuses.","role":"best"},{"name":"Botulism","supports":"Dysphagia and weakness may overlap","against":"Flaccid skeletal muscle paralysis rather than primary enteric ganglion degeneration","hist":"Usually no specific neuronal degenerative lesion","role":"less"},{"name":"Mechanical intestinal obstruction","supports":"Produces ileus and distension","against":"Does not explain simultaneous widespread autonomic signs and ganglion degeneration","hist":"Mechanical obstruction without diffuse ganglioneuritis","role":"less"},{"name":"Equine recurrent laryngeal neuropathy","supports":"Can cause upper-airway dysfunction","against":"Predominantly focal laryngeal dysfunction, not generalized autonomic failure","hist":"Distal axonopathy and cricoarytenoideus muscle atrophy","role":"less"}]},{"id":"n70-schwannoma","lecture":"70","system":"PNS","title":"Peripheral nerve mass in an older dog","species":"Older dog","history":"Slowly progressive unilateral forelimb lameness, pain and muscle atrophy; a fusiform mass follows the brachial plexus and extends along a nerve.","gross":"Firm fusiform enlargement of a peripheral nerve, occasionally extending into the vertebral canal.","histo":"Spindle-cell neoplasm with variable Antoni A and Antoni B areas, nuclear palisading or Verocay bodies in classic schwannoma; confirm lineage by pathology.","best":"Schwannoma / peripheral nerve sheath tumor","morph":"Peripheral nerve: expansile spindle-cell sheath neoplasm","mechanism":"Neoplastic Schwann-cell proliferation compresses and replaces nerve fascicles, causing pain and denervation atrophy.","tests":"Advanced imaging for nerve/foraminal spread, biopsy and histopathology with immunohistochemistry as indicated.","ref":"L70 slides 21–23","options":[{"name":"Schwannoma / peripheral nerve sheath tumor","supports":"The anatomic distribution, signalment and specific lesion pattern favor this diagnosis.","against":"Confirm with appropriate imaging, microscopy and ancillary testing; one finding alone is insufficient.","hist":"Spindle-cell neoplasm with variable Antoni A and Antoni B areas, nuclear palisading or Verocay bodies in classic schwannoma; confirm lineage by pathology.","role":"best"},{"name":"Soft tissue sarcoma","supports":"Can be a spindle-cell limb mass","against":"Not centered on a nerve fascicle and lacks characteristic sheath differentiation","hist":"Pleomorphic fascicular mesenchymal cells","role":"less"},{"name":"Neurofibroma","supports":"Can enlarge a peripheral nerve","against":"Contains a heterogeneous admixture of Schwann, perineurial and fibroblastic cells","hist":"Mixed spindle-cell proliferation with entrapped axons","role":"less"},{"name":"Neuritis","supports":"Causes nerve pain and dysfunction","against":"Inflammatory infiltrate and axonal injury rather than expansile clonal tumor","hist":"Lymphocytes/macrophages and damaged axons","role":"less"}]},
{"id":"n69-hydranencephaly","lecture":"69","system":"CNS / congenital","title":"Newborn calf with a fluid-filled cerebral cavity","species":"Neonatal calf","history":"The calf is severely neurologically abnormal at birth. The cranial vault is formed, but large portions of the cerebral hemispheres are absent and replaced by a fluid-filled membranous sac.","gross":"Near-complete loss of much of the cerebral mantle; leptomeninges surround a large fluid-filled cavity, unlike a simply expanded ventricular space.","histo":"Minimal residual cerebral tissue with evidence of prenatal destructive injury; distinguish a stretched but present cerebral cortical mantle.","best":"Hydranencephaly","morph":"Brain: severe congenital destructive loss of cerebral hemispheres (hydranencephaly)","mechanism":"Prenatal destructive injury, sometimes infectious or vascular, removes previously developing cerebral tissue.","tests":"Careful coronal brain section and fetal/neonatal history; targeted infectious testing if indicated.","ref":"L69 slide 9","options":[{"name":"Hydranencephaly","supports":"The calf is severely neurologically abnormal at birth. The cranial vault is formed, but large portions of the cerebral hemispheres are absent and replaced by a fluid-filled membranous sac. Near-complete loss of much of the cerebral mantle; leptomeninges surround a large fluid-filled cavity, unlike a simply expanded ventricular space.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Minimal residual cerebral tissue with evidence of prenatal destructive injury; distinguish a stretched but present cerebral cortical mantle.","role":"best"},{"name":"Hydrocephalus","supports":"Reasonable competing differential for this presentation.","against":"Ventricular dilation compresses a retained cerebral mantle","hist":"Ventricular dilation compresses a retained cerebral mantle","role":"less"},{"name":"Porencephaly","supports":"Consider when history and localization remain incomplete.","against":"Focal cavity rather than widespread hemispheric destruction","hist":"Focal cavity rather than widespread hemispheric destruction","role":"less"},{"name":"Cerebral aplasia","supports":"A related process can mimic a portion of the findings.","against":"Primary failure of formation rather than destructive cavitation","hist":"Primary failure of formation rather than destructive cavitation","role":"less"}]},
{"id":"n69-hydromyelia","lecture":"69","system":"Spinal cord / congenital","title":"Young dog with dilated spinal central canal","species":"Young dog with progressive spinal neurologic abnormalities","history":"MRI and transverse spinal sections show a fluid-distended central canal, rather than an irregular cavity dissecting into the parenchyma.","gross":"Symmetric central canal expansion along spinal segments.","histo":"Distended central canal lined by residual ependyma; secondary surrounding tissue attenuation possible.","best":"Hydromyelia","morph":"Spinal cord: central canal dilatation (hydromyelia)","mechanism":"Abnormal CSF flow or congenital canal development expands the ependymal-lined lumen.","tests":"MRI and histology to define whether the cavity is continuous with the central canal.","ref":"L69 slide 12","options":[{"name":"Hydromyelia","supports":"MRI and transverse spinal sections show a fluid-distended central canal, rather than an irregular cavity dissecting into the parenchyma. Symmetric central canal expansion along spinal segments.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Distended central canal lined by residual ependyma; secondary surrounding tissue attenuation possible.","role":"best"},{"name":"Syringomyelia","supports":"Reasonable competing differential for this presentation.","against":"Fluid cavity primarily within cord parenchyma and not simply the ependymal canal","hist":"Fluid cavity primarily within cord parenchyma and not simply the ependymal canal","role":"less"},{"name":"Intramedullary neoplasia","supports":"Consider when history and localization remain incomplete.","against":"Solid neoplastic cellular proliferation or secondary cyst","hist":"Solid neoplastic cellular proliferation or secondary cyst","role":"less"},{"name":"Myelomalacia","supports":"A related process can mimic a portion of the findings.","against":"Necrotic debris and macrophages rather than a clean ependymal-lined cavity","hist":"Necrotic debris and macrophages rather than a clean ependymal-lined cavity","role":"less"}]},
{"id":"n69-astrocytoma","lecture":"69","system":"CNS / neoplasia","title":"Brachycephalic dog with infiltrative brain mass","species":"Eight-year-old brachycephalic dog","history":"Progressive seizures and behavioral changes; sectioning the cerebral hemisphere reveals a poorly demarcated pale-pink infiltrative mass with focal necrosis.","gross":"Ill-defined infiltrative cerebral mass, potentially hemorrhagic or necrotic at high grade.","histo":"Neoplastic astrocytic proliferation infiltrating neural parenchyma; microscopic morphology and immunohistochemistry support glial classification.","best":"Astrocytoma","morph":"Cerebrum: infiltrative astrocytic glioma","mechanism":"Neoplastic astrocytes infiltrate and disrupt functional CNS tissue; high-grade tumors develop hypoxia, necrosis and hemorrhage.","tests":"Histopathology with appropriate glial markers and neuroimaging; distinguish from other gliomas.","ref":"L69 slides 18–19","options":[{"name":"Astrocytoma","supports":"Progressive seizures and behavioral changes; sectioning the cerebral hemisphere reveals a poorly demarcated pale-pink infiltrative mass with focal necrosis. Ill-defined infiltrative cerebral mass, potentially hemorrhagic or necrotic at high grade.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Neoplastic astrocytic proliferation infiltrating neural parenchyma; microscopic morphology and immunohistochemistry support glial classification.","role":"best"},{"name":"Oligodendroglioma","supports":"Reasonable competing differential for this presentation.","against":"May be sharply demarcated with uniform round cells and characteristic delicate capillaries","hist":"May be sharply demarcated with uniform round cells and characteristic delicate capillaries","role":"less"},{"name":"Meningioma","supports":"Consider when history and localization remain incomplete.","against":"Extra-axial dural-based mass rather than infiltrating intra-axial tumor","hist":"Extra-axial dural-based mass rather than infiltrating intra-axial tumor","role":"less"},{"name":"Abscess","supports":"A related process can mimic a portion of the findings.","against":"Suppurative necrosis and inflammatory infiltrate rather than glial neoplasia","hist":"Suppurative necrosis and inflammatory infiltrate rather than glial neoplasia","role":"less"}]},
{"id":"n69-choroid-plexus","lecture":"69","system":"CNS / neoplasia","title":"Dog with a fourth-ventricle papillary mass","species":"Older dog","history":"Slowly progressive vestibular deficits and intracranial pressure signs. A granular pink-tan mass occupies the fourth ventricle with ventricular dilation cranial to it.","gross":"Well-defined papillary intraventricular mass with obstruction of CSF pathways and secondary hydrocephalus.","histo":"Frond-like papillae with fibrovascular cores lined by neoplastic epithelial cells; atypia, invasion and mitoses help assess grade.","best":"Choroid plexus tumor","morph":"Fourth ventricle: choroid plexus epithelial neoplasm with obstructive hydrocephalus","mechanism":"A tumor arising from CSF-producing choroid plexus obstructs fluid flow; behavior ranges from papilloma to carcinoma.","tests":"Histopathology, ventricular localization and markers; evaluate invasion to classify tumor.","ref":"L69 slide 23","options":[{"name":"Choroid plexus tumor","supports":"Slowly progressive vestibular deficits and intracranial pressure signs. A granular pink-tan mass occupies the fourth ventricle with ventricular dilation cranial to it. Well-defined papillary intraventricular mass with obstruction of CSF pathways and secondary hydrocephalus.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Frond-like papillae with fibrovascular cores lined by neoplastic epithelial cells; atypia, invasion and mitoses help assess grade.","role":"best"},{"name":"Ependymoma","supports":"Reasonable competing differential for this presentation.","against":"Ependymal rosettes or pseudorosettes rather than papillary choroid plexus morphology","hist":"Ependymal rosettes or pseudorosettes rather than papillary choroid plexus morphology","role":"less"},{"name":"Meningioma","supports":"Consider when history and localization remain incomplete.","against":"Often extra-axial dural association rather than intraventricular origin","hist":"Often extra-axial dural association rather than intraventricular origin","role":"less"},{"name":"Oligodendroglioma","supports":"A related process can mimic a portion of the findings.","against":"Intra-axial glial tumor with different histology and distribution","hist":"Intra-axial glial tumor with different histology and distribution","role":"less"}]},
{"id":"n69-selenium-pig","lecture":"69","system":"CNS / toxicology","title":"Growing pigs with symmetric spinal gray matter malacia","species":"Group of feeder pigs","history":"Several pigs develop hindlimb weakness progressing to recumbency following feed-mixing changes; some have abnormal hair and hooves.","gross":"Bilateral yellow softening of ventral horns of spinal cord gray matter.","histo":"Bilaterally symmetric ventral horn neuronal necrosis and tissue rarefaction with secondary motor neuron loss.","best":"Selenium toxicosis","morph":"Spinal cord: symmetric ventral gray matter poliomyelomalacia","mechanism":"Dietary selenium excess injures spinal ventral gray matter; long-term excess also affects hair and hooves.","tests":"Investigate feed formulation and selenium concentrations in feed and appropriate tissues; rule out other motor disorders.","ref":"L69 slide 28","options":[{"name":"Selenium toxicosis","supports":"Several pigs develop hindlimb weakness progressing to recumbency following feed-mixing changes; some have abnormal hair and hooves. Bilateral yellow softening of ventral horns of spinal cord gray matter.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Bilaterally symmetric ventral horn neuronal necrosis and tissue rarefaction with secondary motor neuron loss.","role":"best"},{"name":"Fumonisin intoxication","supports":"Reasonable competing differential for this presentation.","against":"Horse white-matter leukoencephalomalacia, different host and compartment","hist":"Horse white-matter leukoencephalomalacia, different host and compartment","role":"less"},{"name":"Thiamine deficiency","supports":"Consider when history and localization remain incomplete.","against":"Predominantly cerebral cortical gray matter in ruminant PEM","hist":"Predominantly cerebral cortical gray matter in ruminant PEM","role":"less"},{"name":"Traumatic myelopathy","supports":"A related process can mimic a portion of the findings.","against":"Typically focal and anatomically related to injury rather than bilateral symmetric toxic pattern","hist":"Typically focal and anatomically related to injury rather than bilateral symmetric toxic pattern","role":"less"}]},
{"id":"n69-centaurea","lecture":"69","system":"CNS / toxicology","title":"Horse chewing continuously after thistle exposure","species":"Adult horse during summer forage shortage","history":"Weeks of access to yellow star thistle/Russian knapweed precede inability to prehend feed, incessant chewing and reduced drinking.","gross":"Bilateral, sharply demarcated yellow malacic foci of globus pallidus and substantia nigra.","histo":"Neuronal necrosis and malacia within nigropallidal nuclei.","best":"Centaurea nigropallidal encephalomalacia","morph":"Brain: bilateral nigropallidal neuronal necrosis and malacia","mechanism":"Chronic ingestion of particular Centaurea plants produces selective injury to basal nuclei essential for coordinated feeding behaviors.","tests":"Pasture/botanical history, characteristic basal nuclei distribution and exclusion of alternate neurotoxic exposures.","ref":"L69 slide 36","options":[{"name":"Centaurea nigropallidal encephalomalacia","supports":"Weeks of access to yellow star thistle/Russian knapweed precede inability to prehend feed, incessant chewing and reduced drinking. Bilateral, sharply demarcated yellow malacic foci of globus pallidus and substantia nigra.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Neuronal necrosis and malacia within nigropallidal nuclei.","role":"best"},{"name":"Fumonisin leukoencephalomalacia","supports":"Reasonable competing differential for this presentation.","against":"White matter malacia in horses rather than selectively nigropallidal damage","hist":"White matter malacia in horses rather than selectively nigropallidal damage","role":"less"},{"name":"Equine EPM","supports":"Consider when history and localization remain incomplete.","against":"Multifocal asymmetric inflammatory necrosis, often spinal cord","hist":"Multifocal asymmetric inflammatory necrosis, often spinal cord","role":"less"},{"name":"Polioencephalomalacia","supports":"A related process can mimic a portion of the findings.","against":"Cortical gray matter injury rather than selective globus pallidus/substantia nigra","hist":"Cortical gray matter injury rather than selective globus pallidus/substantia nigra","role":"less"}]},
{"id":"n69-srma","lecture":"69","system":"CNS / immune","title":"Young Beagle with cervical pain and vasculitis","species":"Young Beagle","history":"Acute fever, hunched posture and marked neck hyperesthesia; CSF has pronounced neutrophilic pleocytosis.","gross":"Cervical leptomeningeal petechiae or hemorrhage may be present; other large arteries can also be involved.","histo":"Meningeal arterial fibrinoid necrosis and mixed leukocytic arteritis, sometimes with neutrophilic meningitis.","best":"Steroid-responsive meningitis-arteritis","morph":"Cervical leptomeninges: necrotizing arteritis with neutrophilic meningitis","mechanism":"Immune-mediated arterial inflammation disrupts vessels and irritates meninges, producing pain and CSF neutrophilia.","tests":"CSF analysis and infectious disease exclusion before immune suppression; biopsy if available and clinical response.","ref":"L69 slide 44","options":[{"name":"Steroid-responsive meningitis-arteritis","supports":"Acute fever, hunched posture and marked neck hyperesthesia; CSF has pronounced neutrophilic pleocytosis. Cervical leptomeningeal petechiae or hemorrhage may be present; other large arteries can also be involved.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Meningeal arterial fibrinoid necrosis and mixed leukocytic arteritis, sometimes with neutrophilic meningitis.","role":"best"},{"name":"Bacterial meningitis","supports":"Reasonable competing differential for this presentation.","against":"Neutrophilic CSF overlaps but organisms, septic source and suppurative meningeal exudate favor infection","hist":"Neutrophilic CSF overlaps but organisms, septic source and suppurative meningeal exudate favor infection","role":"less"},{"name":"Cervical disk extrusion","supports":"Consider when history and localization remain incomplete.","against":"Focal structural compression without systemic neutrophilic arteritis","hist":"Focal structural compression without systemic neutrophilic arteritis","role":"less"},{"name":"Meningioma","supports":"A related process can mimic a portion of the findings.","against":"Mass effect rather than multifocal necrotizing arteritis","hist":"Mass effect rather than multifocal necrotizing arteritis","role":"less"}]},
{"id":"n69-edm","lecture":"69","system":"CNS / degeneration","title":"Young horse with symmetric ataxia and no gross CNS lesions","species":"Young horse with progressive proprioceptive ataxia","history":"A young horse develops gradually progressive symmetric ataxia without fever or infectious exposure. Routine necropsy reveals little or no gross CNS change.","gross":"Usually grossly normal spinal cord and brainstem.","histo":"Neuroaxonal dystrophy with axonal spheroids and degeneration in characteristic brainstem/spinal pathways; assess distribution.","best":"Equine degenerative myeloencephalopathy","morph":"CNS: neuroaxonal dystrophy and degenerative myeloencephalopathy","mechanism":"Susceptibility and inadequate vitamin E exposure are associated with axon degeneration; precise pathogenesis remains incompletely established.","tests":"Full neurologic localization, vitamin E history/status, exclusion of cervical compression, and targeted CNS histology.","ref":"L69 slide 49","options":[{"name":"Equine degenerative myeloencephalopathy","supports":"A young horse develops gradually progressive symmetric ataxia without fever or infectious exposure. Routine necropsy reveals little or no gross CNS change. Usually grossly normal spinal cord and brainstem.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Neuroaxonal dystrophy with axonal spheroids and degeneration in characteristic brainstem/spinal pathways; assess distribution.","role":"best"},{"name":"Cervical vertebral stenotic myelopathy","supports":"Reasonable competing differential for this presentation.","against":"Mechanical cervical compression with site-specific tract damage","hist":"Mechanical cervical compression with site-specific tract damage","role":"less"},{"name":"Equine motor neuron disease","supports":"Consider when history and localization remain incomplete.","against":"Older horses with neurogenic muscle atrophy and lower motor neuron pathology","hist":"Older horses with neurogenic muscle atrophy and lower motor neuron pathology","role":"less"},{"name":"Equine protozoal myeloencephalitis","supports":"A related process can mimic a portion of the findings.","against":"Often asymmetric multifocal inflammation/necrosis with organism-specific testing","hist":"Often asymmetric multifocal inflammation/necrosis with organism-specific testing","role":"less"}]},
{"id":"n69-emnd","lecture":"69","system":"CNS / lower motor neuron","title":"Older horse with fasciculations and profound muscle wasting","species":"Middle-aged horse","history":"Gradual weight and muscle loss, trembling and short-strided gait, with preserved awareness and no marked focal spinal compression.","gross":"Diffuse neurogenic muscle atrophy; the nervous system may lack obvious gross lesions.","histo":"Degeneration of lower motor neurons with secondary denervation atrophy in affected muscles.","best":"Equine motor neuron disease","morph":"Motor system: lower motor neuron degeneration with neurogenic muscle atrophy","mechanism":"Oxidative/nutritional factors including vitamin E deficiency have been implicated in lower motor neuron vulnerability.","tests":"Neurologic exam, dietary/vitamin E assessment and appropriate muscle biopsy; distinguish from primary myopathies.","ref":"L69 slide 50","options":[{"name":"Equine motor neuron disease","supports":"Gradual weight and muscle loss, trembling and short-strided gait, with preserved awareness and no marked focal spinal compression. Diffuse neurogenic muscle atrophy; the nervous system may lack obvious gross lesions.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Degeneration of lower motor neurons with secondary denervation atrophy in affected muscles.","role":"best"},{"name":"Equine degenerative myeloencephalopathy","supports":"Reasonable competing differential for this presentation.","against":"Young horses predominantly with upper motor pathway ataxia and axonal spheroids","hist":"Young horses predominantly with upper motor pathway ataxia and axonal spheroids","role":"less"},{"name":"Equine grass sickness","supports":"Consider when history and localization remain incomplete.","against":"Autonomic/enteric neuronal loss and gastrointestinal ileus predominate","hist":"Autonomic/enteric neuronal loss and gastrointestinal ileus predominate","role":"less"},{"name":"Primary myopathy","supports":"A related process can mimic a portion of the findings.","against":"Myofiber necrosis without neurogenic grouped fiber atrophy","hist":"Myofiber necrosis without neurogenic grouped fiber atrophy","role":"less"}]},
{"id":"n69-degenerative-myelo","lecture":"69","system":"CNS / degeneration","title":"Older German shepherd with progressive pelvic limb ataxia","species":"Senior German shepherd dog","history":"Slow progressive nonpainful hindlimb proprioceptive ataxia and weakness; MRI excludes substantial compressive spinal disease.","gross":"Spinal cord often normal to gross inspection; secondary muscle wasting may develop.","histo":"Axonal loss and myelin degeneration, frequently prominent in thoracic spinal cord white matter tracts.","best":"Degenerative myelopathy","morph":"Thoracic spinal cord: chronic tract degeneration / axonopathy","mechanism":"SOD1 risk variants are associated with oxidative-protein injury in susceptible dogs; genotype alone does not prove clinical disease.","tests":"Neurologic localization and MRI to exclude compression, SOD1 risk testing as supportive evidence, and postmortem histology for confirmation.","ref":"L69 slide 55","options":[{"name":"Degenerative myelopathy","supports":"Slow progressive nonpainful hindlimb proprioceptive ataxia and weakness; MRI excludes substantial compressive spinal disease. Spinal cord often normal to gross inspection; secondary muscle wasting may develop.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Axonal loss and myelin degeneration, frequently prominent in thoracic spinal cord white matter tracts.","role":"best"},{"name":"Intervertebral disk extrusion","supports":"Reasonable competing differential for this presentation.","against":"Pain or focal compression and imaging lesion","hist":"Pain or focal compression and imaging lesion","role":"less"},{"name":"Cervical vertebral stenotic myelopathy","supports":"Consider when history and localization remain incomplete.","against":"Cervical compression rather than diffuse thoracic tract degeneration","hist":"Cervical compression rather than diffuse thoracic tract degeneration","role":"less"},{"name":"Fibrocartilaginous embolism","supports":"A related process can mimic a portion of the findings.","against":"Typically peracute asymmetric onset with focal ischemic lesion","hist":"Typically peracute asymmetric onset with focal ischemic lesion","role":"less"}]},
{"id":"n69-cholesterol-granuloma","lecture":"69","system":"CNS / ventricular mass","title":"Old horse with yellow-brown choroid plexus mass","species":"Aged horse","history":"An incidental or symptomatic tan-brown nodular mass is found near the choroid plexus of a lateral ventricle.","gross":"Firm yellow-brown mass arising in choroid plexus; may obstruct ventricular CSF flow.","histo":"Cholesterol clefts and foreign-body giant cells within granulomatous and fibrous tissue, with blood breakdown products.","best":"Cholesterol granuloma (choroid plexus)","morph":"Choroid plexus: cholesterol granuloma / cholesteatoma","mechanism":"Repeated hemorrhage with cholesterol deposition elicits granulomatous foreign-body response and fibrosis.","tests":"Gross location and histology for cholesterol clefts and giant cells; distinguish from neoplastic papillary epithelium.","ref":"L69 slide 56","options":[{"name":"Cholesterol granuloma (choroid plexus)","supports":"An incidental or symptomatic tan-brown nodular mass is found near the choroid plexus of a lateral ventricle. Firm yellow-brown mass arising in choroid plexus; may obstruct ventricular CSF flow.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Cholesterol clefts and foreign-body giant cells within granulomatous and fibrous tissue, with blood breakdown products.","role":"best"},{"name":"Choroid plexus papilloma","supports":"Reasonable competing differential for this presentation.","against":"Papillary neoplastic epithelium rather than cholesterol cleft granuloma","hist":"Papillary neoplastic epithelium rather than cholesterol cleft granuloma","role":"less"},{"name":"Ependymoma","supports":"Consider when history and localization remain incomplete.","against":"Ependymal neoplastic rosettes rather than cholesterol clefts","hist":"Ependymal neoplastic rosettes rather than cholesterol clefts","role":"less"},{"name":"Meningioma","supports":"A related process can mimic a portion of the findings.","against":"Dural-based neoplasm, different anatomic origin","hist":"Dural-based neoplasm, different anatomic origin","role":"less"}]},
{"id":"n70-congenital-hypomyelin","lecture":"70","system":"PNS / congenital","title":"Young dog with hopping gait and weak reflexes","species":"Juvenile dog","history":"An early-onset hopping gait and limb circumduction occur alongside diminished spinal reflexes, without prior traumatic injury.","gross":"Peripheral nerves can appear grossly normal.","histo":"Uniformly thin peripheral myelin sheaths relative to axon diameter without conspicuous myelin debris from acquired breakdown.","best":"Congenital hypomyelinating polyneuropathy","morph":"Peripheral nerves: diffuse hypomyelination","mechanism":"Disrupted myelin development, including MPZ-related disorders, reduces saltatory conduction from early life.","tests":"Electrodiagnostics, peripheral nerve biopsy and genetic testing where available.","ref":"L70 slide 14","options":[{"name":"Congenital hypomyelinating polyneuropathy","supports":"An early-onset hopping gait and limb circumduction occur alongside diminished spinal reflexes, without prior traumatic injury. Peripheral nerves can appear grossly normal.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Uniformly thin peripheral myelin sheaths relative to axon diameter without conspicuous myelin debris from acquired breakdown.","role":"best"},{"name":"Acquired demyelinating polyneuropathy","supports":"Reasonable competing differential for this presentation.","against":"Normal earlier function and myelin breakdown/remyelination rather than developmentally thin sheaths","hist":"Normal earlier function and myelin breakdown/remyelination rather than developmentally thin sheaths","role":"less"},{"name":"Axonotmesis","supports":"Consider when history and localization remain incomplete.","against":"Focal traumatic axonal degeneration, not diffuse congenital myelin defect","hist":"Focal traumatic axonal degeneration, not diffuse congenital myelin defect","role":"less"},{"name":"Cerebellar hypoplasia","supports":"A related process can mimic a portion of the findings.","against":"CNS coordination disorder without generalized peripheral hyporeflexia","hist":"CNS coordination disorder without generalized peripheral hyporeflexia","role":"less"}]},
{"id":"n70-coyotillo","lecture":"70","system":"PNS / toxicology","title":"Calves with high-stepping gait after browsing seeds","species":"Young cattle with hindlimb weakness","history":"Several ruminants develop a high-stepping gait and incoordination after access to coyotillo plant material.","gross":"Nerves may appear normal grossly.","histo":"Primary Schwann cell / myelin injury with peripheral demyelination and variable secondary axon changes.","best":"Coyotillo toxicosis","morph":"Peripheral nerve: acquired primary demyelinating neuropathy","mechanism":"Coyotillo seed toxins injure Schwann-cell myelin, impairing peripheral conduction.","tests":"Exposure verification and targeted nerve histopathology; exclude nutritional and infectious neuropathies.","ref":"L70 slide 15","options":[{"name":"Coyotillo toxicosis","supports":"Several ruminants develop a high-stepping gait and incoordination after access to coyotillo plant material. Nerves may appear normal grossly.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Primary Schwann cell / myelin injury with peripheral demyelination and variable secondary axon changes.","role":"best"},{"name":"Lead-associated neuropathy","supports":"Reasonable competing differential for this presentation.","against":"Different exposure history and potentially axonal/demyelinating changes","hist":"Different exposure history and potentially axonal/demyelinating changes","role":"less"},{"name":"Congenital hypomyelination","supports":"Consider when history and localization remain incomplete.","against":"Developmental thin myelin from puppyhood rather than acquired herd exposure","hist":"Developmental thin myelin from puppyhood rather than acquired herd exposure","role":"less"},{"name":"Spinal cord compression","supports":"A related process can mimic a portion of the findings.","against":"Central tract abnormality with focal lesion rather than diffuse peripheral demyelination","hist":"Central tract abnormality with focal lesion rather than diffuse peripheral demyelination","role":"less"}]},
{"id":"n70-riboflavin","lecture":"70","system":"PNS / nutritional","title":"Chick with curled toes and enlarged sciatic nerves","species":"Growing chickens","history":"Young birds develop progressive weakness and curled-toe paralysis on an unbalanced starter ration.","gross":"Sciatic/peripheral nerves may be swollen.","histo":"Endoneurial edema, myelin degeneration and variable secondary axonal change.","best":"Riboflavin deficiency","morph":"Peripheral nerve: nutritional edematous demyelinating neuropathy","mechanism":"Riboflavin deficiency disrupts cellular energy metabolism, compromising nerve integrity and producing characteristic curled-toe paralysis.","tests":"Ration audit, flock pattern and response to appropriate diet correction; nerve histology if available.","ref":"L70 slide 16","options":[{"name":"Riboflavin deficiency","supports":"Young birds develop progressive weakness and curled-toe paralysis on an unbalanced starter ration. Sciatic/peripheral nerves may be swollen.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Endoneurial edema, myelin degeneration and variable secondary axonal change.","role":"best"},{"name":"Marek disease","supports":"Reasonable competing differential for this presentation.","against":"Lymphoid infiltration/neoplastic nerve enlargement rather than simple nutritional edema","hist":"Lymphoid infiltration/neoplastic nerve enlargement rather than simple nutritional edema","role":"less"},{"name":"Vitamin A deficiency","supports":"Consider when history and localization remain incomplete.","against":"Optic nerve compression/blindness from bony narrowing in calves or pigs","hist":"Optic nerve compression/blindness from bony narrowing in calves or pigs","role":"less"},{"name":"Botulism","supports":"A related process can mimic a portion of the findings.","against":"Neuromuscular transmission block with flaccid paralysis and typically no structural nerve lesions","hist":"Neuromuscular transmission block with flaccid paralysis and typically no structural nerve lesions","role":"less"}]},
{"id":"n70-salinomycin","lecture":"70","system":"PNS / toxicology","title":"Cats develop weakness after contaminated feed","species":"Group of cats","history":"Cats fed a new batch of food develop acute or subacute weakness and ataxia; feed testing identifies unexpected ionophore contamination.","gross":"No reliable distinctive gross peripheral nerve lesion.","histo":"Primary axonal injury with subsequent myelin degeneration in affected peripheral nerves.","best":"Salinomycin-associated toxic axonopathy","morph":"Peripheral nerves: toxic axonal degeneration with secondary demyelination","mechanism":"Ionophore exposure disrupts ionic homeostasis and injures axons; myelin degeneration follows axon damage.","tests":"Feed/toxicology investigation, nerve histology, and other concurrent tissue assessments as appropriate.","ref":"L70 slide 17","options":[{"name":"Salinomycin-associated toxic axonopathy","supports":"Cats fed a new batch of food develop acute or subacute weakness and ataxia; feed testing identifies unexpected ionophore contamination. No reliable distinctive gross peripheral nerve lesion.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Primary axonal injury with subsequent myelin degeneration in affected peripheral nerves.","role":"best"},{"name":"Coyotillo toxicosis","supports":"Reasonable competing differential for this presentation.","against":"Primary Schwann/myelin injury in exposed ruminants rather than axon-first feline ionophore injury","hist":"Primary Schwann/myelin injury in exposed ruminants rather than axon-first feline ionophore injury","role":"less"},{"name":"Congenital hypomyelination","supports":"Consider when history and localization remain incomplete.","against":"Developmental thin myelin without acute feed outbreak","hist":"Developmental thin myelin without acute feed outbreak","role":"less"},{"name":"Botulism","supports":"A related process can mimic a portion of the findings.","against":"Functional blockade of ACh release with little or no axonal pathology","hist":"Functional blockade of ACh release with little or no axonal pathology","role":"less"}]},
{"id":"n70-axonotmesis","lecture":"70","system":"PNS / trauma","title":"Dog with distal nerve degeneration after limb crush","species":"Adult dog after a crush injury","history":"A limb is injured in a vehicle accident. Sensory and motor deficits persist beyond a transient conduction block; the connective tissue sheath of a major nerve remains intact.","gross":"Focally injured peripheral nerve with preserved connective scaffolding; distal muscle atrophy may occur.","histo":"Distal Wallerian degeneration of axons and myelin while endoneurial pathways can guide regeneration.","best":"Axonotmesis","morph":"Peripheral nerve: axonal disruption with preserved supporting connective tissue","mechanism":"Axons are interrupted, triggering distal Wallerian degeneration, but preserved guides permit some regeneration.","tests":"Serial neurologic exams, electrodiagnostics and surgical assessment of nerve continuity.","ref":"L70 slide 20","options":[{"name":"Axonotmesis","supports":"A limb is injured in a vehicle accident. Sensory and motor deficits persist beyond a transient conduction block; the connective tissue sheath of a major nerve remains intact. Focally injured peripheral nerve with preserved connective scaffolding; distal muscle atrophy may occur.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Distal Wallerian degeneration of axons and myelin while endoneurial pathways can guide regeneration.","role":"best"},{"name":"Neurapraxia","supports":"Reasonable competing differential for this presentation.","against":"Conduction block with axons intact and no distal Wallerian degeneration","hist":"Conduction block with axons intact and no distal Wallerian degeneration","role":"less"},{"name":"Neurotmesis","supports":"Consider when history and localization remain incomplete.","against":"Complete disruption of axons plus connective nerve sheaths; poor spontaneous regeneration","hist":"Complete disruption of axons plus connective nerve sheaths; poor spontaneous regeneration","role":"less"},{"name":"Demyelinating polyneuropathy","supports":"A related process can mimic a portion of the findings.","against":"Diffuse acquired myelin pathology rather than focal traumatic axon loss","hist":"Diffuse acquired myelin pathology rather than focal traumatic axon loss","role":"less"}]},
{"id":"n70-sensory-pointer","lecture":"70","system":"PNS / hereditary","title":"Pointer puppy with painless digit self-trauma","species":"Four-month-old English pointer puppy","history":"A young pointer repeatedly chews paws and develops digital wounds with strikingly reduced pain response but preserved interest in mobility.","gross":"Traumatic paw wounds may dominate gross findings; primary sensory nerve lesions are microscopic.","histo":"Dorsal root ganglion and sensory nerve degeneration / loss of sensory neurons and axons.","best":"Hereditary canine sensory neuropathy","morph":"Dorsal root ganglia and sensory nerves: hereditary degeneration","mechanism":"Loss of nociceptive sensory function makes self-mutilation painless, distinguishing it from pruritic dermatitis.","tests":"Sensory neurologic evaluation, lesion distribution, pedigree and biopsy/genetics when supported.","ref":"L70 slide 29","options":[{"name":"Hereditary canine sensory neuropathy","supports":"A young pointer repeatedly chews paws and develops digital wounds with strikingly reduced pain response but preserved interest in mobility. Traumatic paw wounds may dominate gross findings; primary sensory nerve lesions are microscopic.","against":"Gross distribution and pathology must be interpreted with exposure and confirmatory tests; avoid inferring cause from nonspecific features.","hist":"Dorsal root ganglion and sensory nerve degeneration / loss of sensory neurons and axons.","role":"best"},{"name":"Acral lick dermatitis","supports":"Reasonable competing differential for this presentation.","against":"Repetitive licking with preserved pain sensation and behavioral/skin triggers","hist":"Repetitive licking with preserved pain sensation and behavioral/skin triggers","role":"less"},{"name":"Syringomyelia","supports":"Consider when history and localization remain incomplete.","against":"Cervical cord cavitation with altered pain, not primary sensory ganglion degeneration","hist":"Cervical cord cavitation with altered pain, not primary sensory ganglion degeneration","role":"less"},{"name":"Traumatic peripheral nerve transection","supports":"A related process can mimic a portion of the findings.","against":"Focal distribution after injury rather than bilateral juvenile breed-pattern disease","hist":"Focal distribution after injury rather than bilateral juvenile breed-pattern disease","role":"less"}]}];const known=new Set(bank.cases.map(c=>c.id));for(const c of extra){if(!known.has(c.id)){bank.cases.push(c);known.add(c.id)}}})();
